def api(title):
 p={'action':'query','format':'json','titles':'File:'+title,'prop':'imageinfo','iiprop':'url|size|extmetadata','iiurlwidth':'1000'}
 r=urllib.request.Request('https://commons.wikimedia.org/w/api.php?'+urllib.parse.urlencode(p),headers={'User-Agent':UA})
 page=next(iter(json.load(urllib.request.urlopen(r,timeout=30))['query']['pages'].values())); return page['imageinfo'][0]
photos={}
for slug,(city,lat,lon,title,items) in D.items():
 i=api(title); m=i.get('extmetadata',{}); credit=re.sub('<[^>]+>','',m.get('Artist',{}).get('value','')).strip() or 'Wikimedia Commons contributor'; lic=m.get('LicenseShortName',{}).get('value','').strip() or 'See source page'; src=i.get('descriptionurl') or 'https://commons.wikimedia.org/wiki/'+urllib.parse.quote('File:'+title); raw=urllib.request.urlopen(urllib.request.Request(i.get('thumburl') or i['url'],headers={'User-Agent':UA}),timeout=60).read(); im=Image.open(BytesIO(raw)).convert('RGB'); im.thumbnail((640,420),Image.Resampling.LANCZOS); fn=f'{slug}-{re.sub(r"[^a-z0-9]+","-",title.lower()).strip("-")[:35]}.webp'; out=PUBLIC/fn; im.save(out,'WEBP',quality=74,method=6); photos[slug]=(f'/tourism/{fn}',src,credit,lic,title,out.stat().st_size)
def e(s): return s.replace('\\','\\\\').replace('"','\\"').replace('\n',' ')
L=["import type { TourismSpot } from './tourism';",'',"const sourceLabel = 'راهنمای گردشگری و ویکی‌پدیای فارسی';",'',"const makeSpot = (city: string, lat: number, lon: number, item: Omit<TourismSpot, 'latitude'|'longitude'|'tip'|'locationLabel'|'sourceUrl'|'sourceLabel'>, index: number): TourismSpot => ({ ...item, latitude: lat + index * 0.004, longitude: lon + index * 0.004, tip: 'ساعت بازدید و وضعیت دسترسی را پیش از حرکت بررسی کنید و به محیط و حریم جاذبه احترام بگذارید.', locationLabel: city, sourceUrl: `https://fa.wikipedia.org/wiki/${encodeURIComponent(city)}`, sourceLabel });",'', 'export const tourismBatch3: Record<string, TourismSpot[]> = {']
for slug,(city,lat,lon,title,items) in D.items():
 L.append(f'  "{slug}": [')
 for j,(name,cat,desc,dur) in enumerate(items):
  x=f'id: "{slug}-{j+1}", name: "{e(name)}", category: "{cat}", description: "{e(desc)}", duration: "{dur}", icon: "{["🏛️","🌿","🍽️"][j]}", accent: "{["#b45309","#15803d","#b45309"][j]}"'
  if j==0:
   p=photos[slug]; x+=f', imageUrl: "{p[0]}", imageSourceUrl: "{e(p[1])}", imageCredit: "{e(p[2])}", imageLicense: "{e(p[3])}"'
  L.append(f'    makeSpot("{e(city)}", {lat}, {lon}, {{ {x} }}, {j}),')
 L.append('  ],')
L+=['};','']; OUT.write_text('\n'.join(L),encoding='utf8')
with ATTR.open('a',encoding='utf8') as f:
 f.write('\n## تصاویر مرحلهٔ چهارم؛ شهرهای باقی‌مانده\n\n')
 for slug,p in photos.items(): f.write(f'- `{Path(p[0]).name}` — [{p[4]}]({p[1]}), {p[2]}, {p[3]}; بهینه‌شده با WebP ({p[5]:,} bytes).\n')
print('generated',len(photos),'images and',OUT)
